using System.Linq; using System.Data.Entity; using System.Web.Mvc; using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Controllers { public class ProductsController:Controller { private StoreContext db=new StoreContext(); public ActionResult Index(string q,int? categoryId,string sort="name",int page=1){ var x=db.Products.Include(p=>p.Category).AsQueryable(); if(!string.IsNullOrWhiteSpace(q))x=x.Where(p=>p.ProductName.Contains(q)||p.ProductDecription.Contains(q)||p.Category.CategoryName.Contains(q)); if(categoryId.HasValue)x=x.Where(p=>p.CategoryID==categoryId.Value); switch(sort){case "priceup":x=x.OrderBy(p=>p.ProductPrice);break;case "pricedown":x=x.OrderByDescending(p=>p.ProductPrice);break;default:x=x.OrderBy(p=>p.ProductName);break;} ViewBag.Query=q;ViewBag.CategoryId=categoryId;ViewBag.Sort=sort;ViewBag.Page=page;ViewBag.TotalPages=(int)System.Math.Ceiling(x.Count()/8.0);ViewBag.Categories=db.Categories.ToList();return View(x.Skip((page-1)*8).Take(8).ToList());} public ActionResult Details(int id){var p=db.Products.Include(x=>x.Category).FirstOrDefault(x=>x.ProductID==id);if(p==null)return HttpNotFound();return View(p);} protected override void Dispose(bool disposing){if(disposing)db.Dispose();base.Dispose(disposing);} } }